for q in range(int(input())):
	(n, m) = map(int, input().split())
	(l1, l, c, f, r, result) = ([int(x) for x in input().split()], [], [0] * m, 0, 0, 10 ** 10)
	for i in range(0, n):
		l2 = []
		(l2.append(l1[i]), l2.append(i % m))
		l.append(l2)
	l.sort()
	for i in range(n):
		while r < n and f < m:
			if c[l[r][1]] == 0:
				f += 1
			c[l[r][1]] += 1
			r += 1
		if f == m:
			result = min(result, l[r - 1][0] - l[i][0])
		c[l[i][1]] -= 1
		if c[l[i][1]] == 0:
			f -= 1
	print(result)
